// clone returns a concrete clone of the OrderQuery for internal use by First/Only.
func (q *OrderQuery) clone() *OrderQuery {
	if q == nil {
		return nil
	}
	c := &OrderQuery{
		config:        q.config,
		ctx:           q.ctx.Clone(),
		inters:        q.inters,
		modifiers:     runtime.CloneSlice(q.modifiers),
		order:         runtime.CloneSlice(q.order),
		path:          q.path,
		predicates:    runtime.CloneSlice(q.predicates),
		withCustomer:  q.withCustomer.clone(),
		withFKs:       q.withFKs,
		withItems:     q.withItems.clone(),
		withWarehouse: q.withWarehouse.clone(),
	}
	if q.withNamedItems != nil {
		c.withNamedItems = make(map[string]*OrderItemQuery, len(q.withNamedItems))
		for name, q := range q.withNamedItems {
			c.withNamedItems[name] = q.clone()
		}
	}
	return c
}

// loadCustomer eagerly loads the "customer" edge for the given nodes.
func (q *OrderQuery) loadCustomer(ctx context.Context, query *CustomerQuery, nodes []*entity.Order, init func(*entity.Order), assign func(*entity.Order, *entity.Customer)) error {
	query = query.clone()
	fkSeen := make(map[int]struct{}, len(nodes))
	var fks []any
	for _, n := range nodes {
		fkRaw := n.FKValue("customer_orders")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if _, ok := fkSeen[fkVal]; !ok {
			fkSeen[fkVal] = struct{}{}
			fks = append(fks, any(fkVal))
		}
		if init != nil {
			init(n)
		}
	}
	if len(fks) == 0 {
		return nil
	}
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(customer.FieldID), fks...))
	})
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	neighborByID := make(map[int]*entity.Customer, len(neighbors))
	for _, n := range neighbors {
		neighborByID[n.ID] = n
	}
	for _, n := range nodes {
		fkRaw := n.FKValue("customer_orders")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if neighbor, ok := neighborByID[fkVal]; ok {
			assign(n, neighbor)
		}
	}
	return nil
}

