// loadItems eagerly loads the "items" edge for the given nodes.
func (q *OrderQuery) loadItems(ctx context.Context, query *OrderItemQuery, nodes []*entity.Order, init func(*entity.Order), assign func(*entity.Order, *entity.OrderItem)) error {
	query = query.clone()
	fks := make([]any, 0, len(nodes))
	nodeids := make(map[int]*entity.Order, len(nodes))
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	query.withFKs = true
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(order.ItemsColumn), fks...))
	})
	limit, err := runtime.PlanPerParentLimit[int](ctx, query.ctx, query.config.Driver, "items")
	if err != nil {
		return err
	}
	if limit.Active {
		query.modifiers = append(query.modifiers, func(s *sql.Selector) {
			limit.Apply(s, s.C(order.ItemsColumn), s.C(orderitem.FieldID))
		})
	}
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.FKValue("order_items")
		if fk == nil {
			return fmt.Errorf("velox: foreign-key %q is nil for node %v", "order_items", n.ID)
		}
		parentID := derefFK(fk).(int)
		node, ok := nodeids[parentID]
		if !ok {
			return fmt.Errorf("velox: unexpected foreign-key %q returned %v for node %v", "order_items", parentID, n.ID)
		}
		if !limit.Keep(parentID) {
			continue
		}
		assign(node, n)
	}
	return nil
}

